/**
 * Client-local game compile: VPS research → Ollama on laptop → validate on VPS.
 */
import api from './api';
import { generateLocalText, extractRawJson, probeLocalLlm, DEFAULT_MODEL } from './localLlm';

export async function compileGameOnDevice(topic, {
  styleId,
  lessonSnippet,
  model = DEFAULT_MODEL,
  onProgress,
} = {}) {
  onProgress?.('Fetching live research…');
  const research = await api.getResearchContext(topic);
  const style = styleId && styleId !== 'auto' ? styleId : research.suggestedStyle;

  const prompt = research.compilerPrompt;
  if (!prompt) {
    throw new Error('Server did not return compiler prompt');
  }

  onProgress?.('Compiling game on your device…');
  const probe = await probeLocalLlm();
  if (!probe.available) {
    throw new Error('Ollama not running. Start with: ollama serve');
  }

  const modelToUse = probe.models?.includes(model)
    ? model
    : probe.models?.[0] || model;

  const raw = await generateLocalText(prompt, { model: modelToUse, temperature: 0.1 });
  const compiled = extractRawJson(raw);
  if (!compiled) {
    throw new Error('Local model returned invalid JSON. Try a coder model at low temperature.');
  }

  onProgress?.('Validating…');
  const result = await api.submitCompiledGame({ topic, compiled });
  return {
    game: result.game,
    valid: result.valid,
    warning: result.warning,
    provider: 'client-local',
    style_id: compiled.style_id || style,
    model: modelToUse,
  };
}

export async function compileGameHybrid(topic, options = {}) {
  const { preferLocal = false, onProgress, ...rest } = options;

  if (preferLocal) {
    try {
      return await compileGameOnDevice(topic, { ...rest, onProgress });
    } catch (err) {
      onProgress?.(`Local failed (${err.message}), using cloud…`);
    }
  }

  onProgress?.('Compiling on cloud…');
  const result = await api.compileGame({
    topic,
    styleId: rest.styleId,
    lessonSnippet: rest.lessonSnippet,
    provider: 'auto',
  });
  return { ...result, provider: result.provider || 'cloud' };
}
